class NomObra extends BaseNomObra {

    /**
     * Obtener un listado de los datos de los tipos de nómina.
     * 
     * @param int       $inicio Inicio de la busqueda.
      * @param int       $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de los tipos de nómina.
     */
    public static function obtenerListadoObra($inicio = 0, $limite = 10) {
        //Devolviendo el listado de tipos de nómina en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomObra')
				->orderBy('denominacion ASC')
                //->limit($limite)
                //->offset($inicio)
                ->fetchArray();
    }

    /**
     * Obtener la cantidad total de tipos de nómina.
     * 
     * @return int      Cantidad total de tipos de nómina.
     */
    public static function obtenerCantidadTotalObra() {

        //Devolviendo la cantidad total de tipos de nómina.
        return Doctrine_Query::create()->select('COUNT(idobra) AS cantidad')
                        ->from('NomObra')
                        ->fetchOne()
                        ->cantidad;
    }
    
    /**
     * Obtener el obra dado el identificador.
     * 
     * @param int $idobra    Identificador del obra.
     * @return NomObra      Objeto obra (clase del dominio).
     */
    public static function obtenerObjObraDadoId($idobra) {
        return Doctrine::getTable('NomObra')->find($idobra);
    }
    
	/**
     * Obtener si existe un obra a partir de la denominación.
     * 
	 * @param int $idtnomin    		Identificador del obra.
     * @param string $denom    	 	Denominación del obra.
	 *
     * @return boolean    			Si existe un obra.
     */
    public static function existeObra($idobra, $denom) {
		
		$query = Doctrine_Query::create()->select('COUNT(idobra) AS cantidad')
                        ->from('NomObra')
						->where("denominacion ilike ?", $denom);
		if($idobra){
			$query->addWhere('idobra <> ?', $idobra);
		}		
		
		return    $query->fetchOne()->cantidad;
     }

    public function obtenerDenominacion($idobra){
        $sql = Doctrine_Query::create();
        return $sql -> select('denominacion')
                    -> from('NomObra')
                    ->where('idobra = ?', array($idobra))
                    ->fetchOne()
                    ->denominacion;
    }
}
